\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{booktabs}
\usepackage{array}
\usepackage{multirow}
\pagestyle{empty}

% ── Color Theme: Deep Navy + Gold + Teal ──
\definecolor{primary}{HTML}{0B2545}      % deep navy
\definecolor{secondary}{HTML}{1B4F8A}    % medium navy-blue
\definecolor{accent}{HTML}{C9993F}       % gold
\definecolor{tealaccent}{HTML}{0E7C7B}   % teal
\definecolor{bgposter}{HTML}{EEF2F7}     % light blue-grey background
\definecolor{redbg}{HTML}{F0F5FF}        % cool tint for navy cards
\definecolor{bluebg}{HTML}{F5F9FF}       % lighter blue tint
\definecolor{goldbg}{HTML}{FDF8EE}       % gold tint
\definecolor{tealbg}{HTML}{EDFAFA}       % teal tint
\definecolor{redtitlebg}{HTML}{DDE8F5}   % card title bg (navy)
\definecolor{bluetitlebg}{HTML}{E8EFF9}  % card title bg (secondary)
\definecolor{goldtitlebg}{HTML}{F5E9CC}  % card title bg (gold)
\definecolor{tealtitlebg}{HTML}{D4EFEF}  % card title bg (teal)
\definecolor{textdark}{HTML}{0B1F3A}
\definecolor{textgray}{HTML}{3D5A80}
\definecolor{stathighlight}{HTML}{FFF8E8}
\definecolor{goldlight}{HTML}{FAF0D7}
\definecolor{rowalt}{HTML}{E8F0F8}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=8pt, parsep=0pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=8pt, parsep=0pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={6pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.18},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=goldbg,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=goldtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.18},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={6pt}{0pt}{tealaccent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{tealaccent},
    coltitle=tealaccent, colbacktitle=tealtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={tealaccent!40},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={7pt}{0pt}{primary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.25},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

%% ══════════════════════════════════════════════
%% TITLE BAR
%% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=16pt, bottom=14pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35},
  underlay={
    \fill[accent!30, opacity=0.25] ([xshift=0pt,yshift=0pt]frame.south west)
      rectangle ([xshift=120pt,yshift=0pt]frame.north west);
    \fill[accent!30, opacity=0.25] ([xshift=-120pt,yshift=0pt]frame.south east)
      rectangle ([xshift=0pt,yshift=0pt]frame.north east);
  }
]{name=title, column=1, span=3, between=top and row4}{%
  {\fontsize{26}{32}\selectfont\bfseries\color{accent!80!white}%
    QS WORLD UNIVERSITY RANKINGS}\\[6pt]
  {\fontsize{76}{90}\selectfont\bfseries\color{white}%
    Top Global Universities}\\[8pt]
  {\fontsize{52}{62}\selectfont\bfseries\color{white}%
    Compared \textemdash\ 2026 Edition}\\[14pt]
  {\fontsize{30}{38}\selectfont\color{white!75}%
    A data-driven analysis of 1,500$+$ institutions across 105 countries}%
}

%% ══════════════════════════════════════════════
%% STATS BANNER
%% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  borderline south={4pt}{0pt}{accent!60},
  borderline north={2pt}{0pt}{primary!25},
  left=10pt, right=10pt, top=8pt, bottom=8pt,
  valign=center,
]{name=stats, column=1, span=3, between=row4 and row7}{%
  \centering
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{primary} 100}\\[4pt]
      {\fontsize{26}{32}\selectfont\bfseries\color{accent} PERFECT SCORE}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} MIT \#1 Worldwide}\vspace{8pt}%
    }}%
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{primary} 1,500+}\\[4pt]
      {\fontsize{26}{32}\selectfont\bfseries\color{accent} UNIVERSITIES}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Evaluated Globally}\vspace{8pt}%
    }}%
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{primary} 105}\\[4pt]
      {\fontsize{26}{32}\selectfont\bfseries\color{accent} COUNTRIES}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Represented 2026}\vspace{8pt}%
    }}%
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{primary} 27}\\[4pt]
      {\fontsize{26}{32}\selectfont\bfseries\color{accent} US UNIVERSITIES}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} in Top 100}\vspace{8pt}%
    }}%
  \end{minipage}\hfill
  \begin{minipage}[c]{0.185\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.90\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{74}\selectfont\bfseries\color{primary} 17}\\[4pt]
      {\fontsize{26}{32}\selectfont\bfseries\color{accent} UK UNIVERSITIES}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} in Top 100}\vspace{8pt}%
    }}%
  \end{minipage}%
}

%% ══════════════════════════════════════════════
%% COLUMN 1: TOP 10 TABLE (CENTERPIECE)
%% ══════════════════════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=primary!96!black,
  borderline west={0pt}{0pt}{primary},
  left=0pt, right=0pt, top=0pt, bottom=0pt,
  valign=top,
  drop shadow={opacity=0.30},
]{name=topten, column=1, span=3, between=row7 and row14}{%
  % Header bar
  \begin{tcolorbox}[
    enhanced, arc=0pt, boxrule=0pt,
    colback=primary, colframe=primary,
    left=20pt, right=20pt, top=10pt, bottom=10pt,
  ]
    \centering
    {\fontsize{42}{50}\selectfont\bfseries\color{accent}%
      \rule[0.5ex]{60pt}{2pt}\quad THE TOP 10 \quad\rule[0.5ex]{60pt}{2pt}}\\[4pt]
    {\fontsize{26}{32}\selectfont\color{white!80}%
      QS World University Rankings 2026 — Overall Score (out of 100)}
  \end{tcolorbox}
  % Table
  \begin{center}
  \fontsize{30}{40}\selectfont
  \renewcommand{\arraystretch}{1.55}
  \setlength{\tabcolsep}{0pt}
  \begin{tabular}{
    >{\columncolor{primary!90!black}\centering\arraybackslash}p{70pt}%
    >{\columncolor{primary!85!black}\raggedright\arraybackslash}p{430pt}%
    >{\columncolor{primary!80!black}\centering\arraybackslash}p{220pt}%
    >{\columncolor{primary!75!black}\centering\arraybackslash}p{160pt}%
  }
  % Header row
  {\color{accent}\bfseries Rank} &
  {\color{accent}\bfseries\hspace{16pt}University} &
  {\color{accent}\bfseries Score} &
  {\color{accent}\bfseries Country} \\[-2pt]
  \arrayrulecolor{accent!40}\hline
  % Row 1 — MIT highlighted
  {\cellcolor{accent!35}\color{white}\bfseries\fontsize{36}{44}\selectfont 1} &
  {\cellcolor{accent!25}\color{white}\bfseries\fontsize{32}{40}\selectfont\hspace{16pt}Massachusetts Institute of Technology} &
  {\cellcolor{accent!25}\color{white}\bfseries\fontsize{36}{44}\selectfont 100.0} &
  {\cellcolor{accent!25}\color{white}\bfseries\fontsize{28}{36}\selectfont United States} \\
  \arrayrulecolor{primary!60}\hline
  {\color{white!90} 2} & {\color{white!90}\hspace{16pt}Imperial College London} & {\color{white!90} 98.5} & {\color{white!80} United Kingdom} \\
  \hline
  {\cellcolor{rowalt!25}\color{white!90} 3} & {\cellcolor{rowalt!25}\color{white!90}\hspace{16pt}University of Oxford} & {\cellcolor{rowalt!25}\color{white!90} 97.9} & {\cellcolor{rowalt!25}\color{white!80} United Kingdom} \\
  \hline
  {\color{white!90} 4} & {\color{white!90}\hspace{16pt}Harvard University} & {\color{white!90} 97.6} & {\color{white!80} United States} \\
  \hline
  {\cellcolor{rowalt!25}\color{white!90} 5} & {\cellcolor{rowalt!25}\color{white!90}\hspace{16pt}University of Cambridge} & {\cellcolor{rowalt!25}\color{white!90} 97.0} & {\cellcolor{rowalt!25}\color{white!80} United Kingdom} \\
  \hline
  {\color{white!90} 6} & {\color{white!90}\hspace{16pt}Stanford University} & {\color{white!90} 96.8} & {\color{white!80} United States} \\
  \hline
  {\cellcolor{rowalt!25}\color{white!90} 7} & {\cellcolor{rowalt!25}\color{white!90}\hspace{16pt}ETH Zurich} & {\cellcolor{rowalt!25}\color{white!90} 95.3} & {\cellcolor{rowalt!25}\color{white!80} Switzerland} \\
  \hline
  {\color{white!90} 8} & {\color{white!90}\hspace{16pt}Nat.\ University of Singapore (NUS)} & {\color{white!90} 94.7} & {\color{white!80} Singapore} \\
  \hline
  {\cellcolor{rowalt!25}\color{white!90} 9} & {\cellcolor{rowalt!25}\color{white!90}\hspace{16pt}UCL (University College London)} & {\cellcolor{rowalt!25}\color{white!90} 94.2} & {\cellcolor{rowalt!25}\color{white!80} United Kingdom} \\
  \hline
  {\color{white!90} 10} & {\color{white!90}\hspace{16pt}California Institute of Technology} & {\color{white!90} 93.8} & {\color{white!80} United States} \\
  \end{tabular}
  \end{center}
}

%% ══════════════════════════════════════════════
%% COLUMN 1: METHODOLOGY
%% ══════════════════════════════════════════════
\posterbox[navycard, title={How Are Universities Ranked?}
]{name=methodology, column=1, between=row14 and row20}{%
  \fontsize{30}{40}\selectfont
  {\fontsize{26}{32}\selectfont\color{textgray}
  Six core indicators drive the QS score. Academic Reputation alone
  — surveying \textbf{130,000+ academics} globally — accounts for nearly half the total.}
  \vspace{10pt}

  \renewcommand{\arraystretch}{1.55}
  \setlength{\tabcolsep}{0pt}
  \fontsize{28}{36}\selectfont
  \begin{tabular}{
    >{\raggedright\arraybackslash}p{265pt}%
    >{\centering\arraybackslash}p{90pt}%
    >{\raggedright\arraybackslash}p{240pt}%
  }
  \rowcolor{primary!18}
  {\bfseries\color{primary} Indicator} & {\bfseries\color{primary} Weight} & {\bfseries\color{primary} What It Measures} \\
  \rowcolor{accent!22}
  Academic Reputation & \bfseries\color{accent} 40\% & Global scholar survey \\
  \rowcolor{primary!10}
  Faculty/Student Ratio & \bfseries\color{secondary} 20\% & Teaching capacity \\
  \rowcolor{accent!12}
  Citations per Faculty & \bfseries\color{secondary} 20\% & Research impact \\
  \rowcolor{primary!10}
  Employer Reputation & \bfseries\color{secondary} 10\% & Graduate outcomes \\
  \rowcolor{accent!12}
  Intl.\ Faculty Ratio & \bfseries\color{secondary} 5\% & Global diversity \\
  \rowcolor{primary!10}
  Intl.\ Students Ratio & \bfseries\color{secondary} 5\% & Campus diversity \\
  \end{tabular}

  \vspace{12pt}
  \colorbox{accent!22}{\parbox{0.96\linewidth}{%
    \fontsize{26}{34}\selectfont\color{textdark}
    \hspace{6pt}$\blacktriangleright$\enskip
    \textbf{Academic Reputation (40\%)} is the single most influential metric —
    derived from a global survey of over 130,000 academics worldwide.\hspace{4pt}
  }}
}

%% ══════════════════════════════════════════════
%% COLUMN 2: REGIONAL BREAKDOWN
%% ══════════════════════════════════════════════
\posterbox[bluecard, title={Regional Representation: Top 100}
]{name=regional, column=2, between=row14 and row20}{%
  \fontsize{30}{40}\selectfont
  {\fontsize{26}{32}\selectfont\color{textgray}
  Europe leads all regions with \textbf{38 universities} in the global top 100,
  driven by the UK's exceptional strength.}
  \vspace{10pt}

  % Visual bar chart using TikZ-free approach with colored boxes
  \newlength{\barmax}
  \setlength{\barmax}{390pt}

  % Europe: 38
  \noindent
  \colorbox{secondary!75}{\parbox{0.96\linewidth}{%
    \fontsize{27}{34}\selectfont\color{white}\bfseries
    \hspace{8pt}Europe\hfill 38 universities\hspace{8pt}
  }}\\[4pt]

  % North America: 30
  \colorbox{primary!80}{\parbox{0.756\linewidth}{%
    \fontsize{27}{34}\selectfont\color{white}\bfseries
    \hspace{8pt}North America\hfill 30\hspace{8pt}
  }}\\[4pt]

  % Asia-Pacific: 26
  \colorbox{tealaccent!80}{\parbox{0.655\linewidth}{%
    \fontsize{27}{34}\selectfont\color{white}\bfseries
    \hspace{8pt}Asia-Pacific\hfill 26\hspace{8pt}
  }}\\[4pt]

  % Middle East & Africa: 4
  \colorbox{accent!70}{\parbox{0.13\linewidth}{%
    \fontsize{23}{30}\selectfont\color{white}\bfseries
    \hspace{4pt}ME\&A: 4\hspace{4pt}
  }}\hspace{6pt}%
  \colorbox{textgray!60}{\parbox{0.10\linewidth}{%
    \fontsize{23}{30}\selectfont\color{white}\bfseries
    \hspace{4pt}LATAM: 2\hspace{4pt}
  }}\\[10pt]

  \renewcommand{\arraystretch}{1.45}
  \setlength{\tabcolsep}{0pt}
  \fontsize{26}{34}\selectfont
  \begin{tabular}{
    >{\raggedright\arraybackslash}p{215pt}%
    >{\centering\arraybackslash}p{80pt}%
    >{\raggedright\arraybackslash}p{260pt}%
  }
  \rowcolor{secondary!18}
  {\bfseries\color{secondary} Region} & {\bfseries\color{secondary} Top 100} & {\bfseries\color{secondary} Standout Countries} \\
  \rowcolor{secondary!10}
  Europe & \bfseries 38 & UK (17), Germany, France \\
  \rowcolor{secondary!05}
  North America & \bfseries 30 & USA (27), Canada (3) \\
  \rowcolor{secondary!10}
  Asia-Pacific & \bfseries 26 & SG, CN, KR, AU \\
  \rowcolor{secondary!05}
  Middle East \& Africa & \bfseries 4 & UAE, SA \\
  \rowcolor{secondary!10}
  Latin America & \bfseries 2 & BR, MX \\
  \end{tabular}

  \vspace{10pt}
  \colorbox{tealaccent!20}{\parbox{0.96\linewidth}{%
    \fontsize{26}{33}\selectfont\color{textdark}
    \hspace{6pt}$\blacktriangleright$\enskip
    \textbf{Asia-Pacific} is the fastest-growing region — Singapore, China,
    South Korea \& Australia all feature prominently.\hspace{4pt}
  }}
}

%% ══════════════════════════════════════════════
%% COLUMN 3: KEY TRENDS
%% ══════════════════════════════════════════════
\posterbox[tealcard, title={Key Trends for 2026}
]{name=trends, column=3, between=row14 and row20}{%
  \fontsize{30}{40}\selectfont
  {\fontsize{26}{32}\selectfont\color{textgray}
  The 2026 edition reflects shifting global priorities in research investment,
  international collaboration, and employability.}
  \vspace{12pt}

  \colorbox{tealaccent!20}{\parbox{0.96\linewidth}{%
    \fontsize{27}{35}\selectfont\color{textdark}
    \hspace{6pt}\textbf{\color{tealaccent}01 \quad Asian Rise}\\[3pt]
    \hspace{6pt}Chinese \& South Korean institutions climb significantly
    — reflecting sustained R\&D investment and global collaboration.
  }}
  \vspace{8pt}

  \colorbox{primary!12}{\parbox{0.96\linewidth}{%
    \fontsize{27}{35}\selectfont\color{textdark}
    \hspace{6pt}\textbf{\color{primary}02 \quad UK Strength Persists}\\[3pt]
    \hspace{6pt}4 UK universities in top 10 and 17 in top 100 — second most
    represented nation after the United States.
  }}
  \vspace{8pt}

  \colorbox{accent!22}{\parbox{0.96\linewidth}{%
    \fontsize{27}{35}\selectfont\color{textdark}
    \hspace{6pt}\textbf{\color{accent}03 \quad Sustainability \& Employability}\\[3pt]
    \hspace{6pt}QS expands supplementary rankings to include sustainability
    metrics and employer outcomes — reflecting evolving priorities.
  }}
  \vspace{8pt}

  \colorbox{secondary!18}{\parbox{0.96\linewidth}{%
    \fontsize{27}{35}\selectfont\color{textdark}
    \hspace{6pt}\textbf{\color{secondary}04 \quad Most Comprehensive Yet}\\[3pt]
    \hspace{6pt}Over 1,500 institutions evaluated across 105 countries —
    the broadest QS ranking to date.
  }}
  \vspace{10pt}

  \begin{itemize}[itemsep=6pt]
    \item[\color{accent}$\star$] MIT holds \#1 for a \textbf{record-extending streak}
